const YG_T = { kaki: 'Kaki', pinggul: 'Pinggul', punggung: 'Punggung', inti: 'Inti', bahu: 'Bahu', dada: 'Dada', lengan: 'Lengan', keseimbangan: 'Keseimbangan', relaksasi: 'Relaksasi', leher: 'Leher', pergelangan: 'Pergelangan' };
