  aiSave(); chatPaint(); renderAiBox();
  const nb = [...$('#chatSet').querySelectorAll('[data-f]')].find(b => b.dataset.f + '|' + b.dataset.v === k); if (nb && !nb.disabled) nb.focus();   // fokus tetap di pilihan yang diketuk (papan ketik)
