function adjEnsure() { if (!pdb.adj || !Array.isArray(pdb.adj.log)) pdb.adj = { mode: 'auto', dis: null, log: [] }; return pdb.adj; }
/* gambar ulang Peta tanpa menutup <details> fase yang sedang dibuka */
