  sl_rdl: { r: [10, 12], per: 'kaki' }, sl_hipthrust: { r: [10, 12], per: 'kaki' }, pistol: { r: [3, 6], per: 'kaki' }, shrimp: { r: [3, 6], per: 'kaki' },
