    plTile(r.elig ? r.stag + '<small>/' + r.elig + '</small>' : '–', 'gerakan stagnan') + plTile(r.rpe.n >= 3 ? fmt(r.rpe.avg, 1) : '–', 'RPE rata-rata 14 hari') + '</div>';
