    (r.max == null ? '' : '<div class="plbar" role="img" aria-label="' + esc('Nyeri tertinggi ' + r.max + ' dari 10') + '"><i class="' + cls + '" style="--w:' + (r.max * 10) + '%"></i></div>') +
    '<small>' + esc(bits.join(' · ')) + '</small>' + (r.lastN ? '<small>“' + esc(r.lastN) + '”</small>' : '') + '</div>';
