  const tags = (arr, on) => arr.length ? arr.map(k => '<button class="pmtag' + (on ? ' on' : '') + '" data-q="pmMus" data-k="' + k + '">' + esc(B18_MUS[k]) + '</button>').join('') : '<span class="pmnone">–</span>';
