  if (W.m) L.push(W.n + ' dari ' + W.m + ' sesi terjadwal terlaksana' + (W.n ? ', ' + W.nT + ' sesuai jenis' : '') + '.');
  if (W.extra) L.push(W.extra + ' ride di luar jadwal.');
