        if (S.dur) bits.push('durasi rata-rata ' + fmt(g.d, 0) + ' menit (' + g.dn + ' ride)');
        if (S.ml) bits.push('minum rata-rata ' + fmt(g.m, 0) + ' ml (' + g.mn + ' ride)');
        if (!bits.length) bits.push('durasi dan minum belum cukup diisi untuk dibandingkan');
