window.DL = Object.freeze(Object.assign({}, window.DL, { b46q6b1: Object.freeze({ csv: toFtpCSV }), b47q6b2: Object.freeze({ svg: ftChartSVG, html: ftChartHTML, max: FT_CH_MAX }), b48q6b3: Object.freeze({ lines: b48FtpLines }) }));
