function clPaint() { const b = $('#clBox'); if (!b) return; b.innerHTML = clInner(); clBtn(); }
function clHTML() { return '<div class="clx" id="clBox">' + clInner() + '</div>'; }
function clAfter() { if (!CL.ready && !CL.loading) clLoad(); clBtn(); }
