const kmtFold = s => String(s == null ? '' : s).toLowerCase().replace(/(?<=\p{L})[013-5@$](?=\p{L})/gu, c => KMT_LEET[c] || c).replace(/(\p{L})\1+/gu, '$1');   // huruf diulang dikecilkan ("anjiiing" -> "anjing"), angka di tengah huruf dibaca huruf ("k4mpr3t")
