  const inf = D.info(c.v.c.n.code), feel = hrFin(a.ap) && Math.abs(a.ap - a.t) >= 2 ? ' · terasa ' + D.T(a.ap) : '';
  const sub = 'Hari ini ' + D.T(a.tmin) + ' sampai ' + D.T(a.tmax) + (hrFin(a.popHari) ? ' · peluang hujan ' + Math.round(a.popHari) + '%' : '');
