  const hRaw = own(profile, 'tinggi'), hNum = isEmpty(hRaw) ? null : parse(hRaw);
  const tinggiOk = hNum !== null && hNum >= STB_LIM.tinggi[0] && hNum <= STB_LIM.tinggi[1];
  const jkRaw = own(profile, 'jk'), jk = jkRaw === 'L' || jkRaw === 'P' ? jkRaw : '';
