const STB_RL = Object.freeze({ dadaPinggang: 'Dada ÷ perut', pahaPinggang: 'Paha ÷ perut', lenganPinggang: 'Lengan ÷ perut', pinggangTinggi: 'Perut ÷ tinggi' });
