  const ok = typeof n === 'string' && STB_SAVE.kontras.indexOf(n) >= 0;
  return Object.freeze({ ada: ok, n: ok ? n : '', teks: ok ? 'Kontras kamu: ' + n + '.' : 'Kontras belum dipilih.', arti: ok ? STB_KN.arti[n] : '' });
