    const pesan = j.ok ? hffPesanAksi('ok_baru_jadwal') : j.kode === 'tidak_ada' ? hffPesanAksi('ok_baru') : 'Kartu disimpan, tetapi belum masuk jadwal hafalan: ' + alasan + '. Kamu bisa memasukkannya nanti.';
