  if (raw.days && typeof raw.days === 'object' && !Array.isArray(raw.days)) {
    Object.keys(raw.days).forEach(d => { if (DATE_RE.test(d) && d <= addDays(today(), 1)) { const x = scCleanDay(raw.days[d]); if (x.ck.length || x.u || scDayHas(x)) b.days[d] = x; } });
  }
