  const wv = scWaterV(t), sh = scSleepH(t);
  const days7 = [0, 1, 2, 3, 4, 5, 6].map(i => addDays(t, -i)), rec = days7.filter(d => scScore(d).any), av = rec.length ? Math.round(rec.reduce((a, d) => a + scScore(d).pts, 0) / rec.length) : null;
