  if (VT.st === 'error') return vtHead('') + '<p class="sc-warn" role="alert">' + esc(VT.fatal) + '</p><div class="sc-row" style="margin-top:8px"><button class="sc-btn" data-q="vtRetry" data-fk="vt-retry">Coba lagi</button></div></section>';
