const GD_TKPI = [];
GD_TKPI_RAW.forEach(r => { const x = gdItem({ id: 'tkpi:' + r[0], n: r[1], src: 'tkpi', v: { kcal: r[2], p: r[3], f: r[4], c: r[5], fiber: r[6], sugar: null, na: r[7], k: r[8], mg: null }, por: [], at: 0 }); if (x) GD_TKPI.push(x); });
